let GEN=null;
let filling=null,lastNav=0;
async function fill(){
  if(filling)return filling;
  filling=(async()=>{
    const c=await caches.open(CACHE),f=await caches.open(FILES);
    const have=new Set((await c.keys()).concat(await f.keys()).map(r=>new URL(r.url).pathname));
    const skip=new Set(GEN==='boy'?ONLYG:GEN==='girl'?ONLYB:[]);const todo=ALL.filter(u=>!have.has(u)&&!skip.has(u)); // ALL is already ordered: pages, small files, pictures and sounds by size, videos last
    // remove old pictures no longer used by the site
    const keep=new Set(ALL);for(const r of await f.keys()){const p=new URL(r.url).pathname;if(!keep.has(p))f.delete(r)}
    await new Promise(r=>setTimeout(r,3000)); // let the open page load first
    let i=0;
    // 4 files at a time; step aside for a moment whenever the child opens a page
    const nap=ms=>new Promise(r=>setTimeout(r,ms));
    const worker=async()=>{while(i<todo.length){while(Date.now()-lastNav<2500)await nap(500);await save(c,todo[i++]);}};
    await Promise.all([worker(),worker(),worker()]);
    filling=null;
    const left=ALL.filter(u=>!have.has(u)).length;
    report();
  })();
  return filling;
}
async function status(){
  const c=await caches.open(CACHE),f=await caches.open(FILES);
  const have=new Set((await c.keys()).concat(await f.keys()).map(r=>new URL(r.url).pathname));
  const skip=new Set(GEN==='boy'?ONLYG:GEN==='girl'?ONLYB:[]);const need=ALL.filter(u=>!skip.has(u)); // the other character's pictures are not needed
  const done=need.filter(u=>have.has(u)).length;
  return {done,total:need.length};
}
async function report(){
  const s=await status();
  const cl=await self.clients.matchAll({includeUncontrolled:true});
  cl.forEach(d45a0bd5f037d4=>d45a0bd5f037d4.postMessage({type:'offline-status',...s}));
}
